    "evidencias": [
      {"fonte_id": "f_bbb437fd83", "localizador": "L06"},
      {"fonte_id": "f_04054cfee1", "localizador": "L01"}
    ],
    "lacunas": [],
    "motivo": "A linha base declarada termina em D10; a unidade é dia corrido.",
    "unidade": "dia_corrido"
  },
  "fim_novo": {
    "estado": "exato",
    "valor": 10,
    "direcao": "desconhecida",
    "evidencias": [
      {"fonte_id": "f_bbb437fd83", "localizador": "L06"},
      {"fonte_id": "f_11ebeff90b", "localizador": "L02"},
      {"fonte_id": "f_0ad555e744", "localizador": "L01"},
      {"fonte_id": "f_e3f0ade479", "localizador": "L01"},
      {"fonte_id": "f_359bae5d73", "localizador": "L03"}
    ],
    "lacunas": [],
    "motivo": "O cartucho substituto mantém a disponibilidade em D2, e o aceite da equivalência mantém a montagem no procedimento padrão de três dias. O aviso não altera as demais condições; portanto, não altera o término da linha base.",
    "unidade": "dia_corrido"
  },
  "delta_dias": {
    "estado": "exato",
    "valor": 0,
    "direcao": "zero",
    "evidencias": [
      {"fonte_id": "f_bbb437fd83", "localizador": "L06"},
      {"fonte_id": "f_0ad555e744", "localizador": "L01"},
      {"fonte_id": "f_11ebeff90b", "localizador": "L02"},
      {"fonte_id": "f_e3f0ade479", "localizador": "L01"}
    ],
    "lacunas": [],
    "motivo": "A disponibilidade do cartucho permanece em D2 e a duração da montagem permanece padrão; não há alteração de prazo frente à linha base.",
    "unidade": "dia_corrido"
  },
  "custo_base": {
    "estado": "exato",
    "valor": 500000,
    "direcao": "desconhecida",
    "evidencias": [
      {"fonte_id": "f_bbb437fd83", "localizador": "L06"}
    ],
    "lacunas": [],
    "motivo": "Orçamento de referência declarado de R$5.000,00.",
    "unidade": "BRL_centavo"
  },
  "custo_novo": {
    "estado": "exato",
    "valor": 530000,
    "direcao": "desconhecida",
    "evidencias": [
      {"fonte_id": "f_bbb437fd83", "localizador": "L06"},
      {"fonte_id": "f_0ad555e744", "localizador": "L01"},
      {"fonte_id": "f_77c5d27cd0", "localizador": "L02"}
    ],
    "lacunas": [],
    "motivo": "Ao orçamento de R$5.000,00 soma-se a taxa única adicional de R$300,00. Como o término permanece em D10, não há extensão além de dez dias.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "exato",
    "valor": 30000,
    "direcao": "aumento",
    "evidencias": [
      {"fonte_id": "f_0ad555e744", "localizador": "L01"},
      {"fonte_id": "f_259da44f35", "localizador": "L03"},
      {"fonte_id": "f_bbb437fd83", "localizador": "L06"}
    ],
    "lacunas": [],
    "motivo": "A taxa adicional expressa de R$300,00 não está incluída no orçamento original e aumenta o custo em 30.000 centavos.",
    "unidade": "BRL_centavo"
  },
  "justificativa": "O aviso mantém a disponibilidade do cartucho em D2 e, com o laudo aceito, mantém a duração padrão da montagem; assim, o término permanece em D10. A taxa única de troca de R$300,00 eleva o custo total de 500.000 para 530.000 centavos."
}

